      "pins": ["U2.1", "U3.1", "U2.2", "U3.2", "U2.3", "U3.3", "U2.4", "U3.4", "U2.5", "U3.5", "U2.6", "U3.6", "U2.7", "U3.7", "U2.8", "U3.8"],
      "nets": ["RST", "POT", "TACH", "GND", "SDA", "PWM", "SCK", "+5V"],
      "observed": "Both an ATtiny45 (U2) and an ATtiny13 (U3) are present, powered from the same rails, and connected pin-for-pin to the same reset and signal nets.",
      "expected": "A fan controller described as ATtiny-driven should have one MCU driving these shared signals, or explicit selection/isolation if the parts are alternatives. Two populated MCUs on the same I/O nets can contend when their GPIO outputs differ.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "U2 | ATtiny45-20P"
        },
        {
          "source": "netlist",
          "quote": "U3 | ATtiny13V-10S"
        },
        {
          "source": "netlist",
          "quote": "PWM : ... U2.6(PB1,bidirectional) U3.6(PB1,bidirectional)"
        },
        {
          "source": "netlist",
          "quote": "SCK : ... U2.7(PB2,bidirectional) U3.7(PB2,bidirectional)"
        },
        {
          "source": "spec",
          "quote": "an ATtiny-driven fan controller"
        }
      ],
      "impact": "If both MCUs are assembled, their outputs can conflict on shared GPIO nets, causing incorrect control signals or excessive output current. Even when their outputs agree, the design has two active controllers where the described design calls for an ATtiny-driven controller.",
      "confidence": 0.82
    },
    {
      "category": "wrong_value",
      "components": ["R5"],
      "pins": ["R5.1", "R5.2", "U2.6", "U3.6", "J2.4"],
      "nets": ["/PWM_OUT", "PWM"],
      "observed": "R5 is 1 MΩ in series between the MCU PWM net and fan connector J2.4.",
      "expected": "The fan PWM interface needs a sufficiently strong low-going drive, typically using an open-collector/open-drain stage or a much lower series resistance. A 1 MΩ series resistor is too large to reliably pull the fan input low against its pull-up.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "R5 | 1M"
        },
        {
          "source": "netlist",
          "quote": "/PWM_OUT : J2.4(Pin_4,passive) R5.1(passive)"
        },
        {
          "source": "netlist",
          "quote": "PWM : ... R5.2(passive) U2.6(PB1,bidirectional) U3.6(PB1,bidirectional)"
        },
        {
          "source": "spice",
          "quote": "R5 /PWM_OUT PWM 1Meg"
        },
        {
          "source": "spec",
          "quote": "an ATtiny-driven fan controller"
        }
      ],
      "impact": "The fan may not recognize the PWM low level, so speed control can fail or behave unpredictably.",
      "confidence": 0.9
    }
  ],
  "summary": "The netlist connects two powered ATtiny devices to the same control nets without showing selection or isolation. It also puts 1 MΩ in series with the fan PWM output, likely preventing a reliable low-level drive."
}

